Generate a consistent OWL ontology in Turtle for domain 'school'. Use absolute HTTP(S) IRIs. Return a JSON object with generated_onto (a Turtle string) and target_property (an absolute IRI). Include a declared object property typed owl:TransitiveProperty; identify it using target_property in the returned object. Use only named entities: no blank nodes, anonymous restrictions, RDF lists or imports. Other named classes and properties may provide domain context. Do not materialize inferred facts. Individuals, benchmark chains, distractor facts and queries will be inserted by a separate builder; do not generate them or answer any benchmark query. For only_symbolic use neutral symbols without domain meanings.
GENERATION CONFIGURATION:
{"direct_assertion_control": false, "domain": "school", "generator": "llm", "max_generation_attempts": 3, "n_distractor_triples": 10, "n_queries": 1, "path_length": 3, "seed": 20261002}

message.content:
{
  "generated_onto": "@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

<https://example.org/school/ontology> a owl:Ontology ;
    rdfs:label "School Domain Ontology" .

<https://example.org/school/class/Teacher> a owl:Class ;
    rdfs:label "Teacher" .

<https://example.org/school/class/Student> a owl:Class ;
    rdfs:label "Student" .

<https://example.org/school/class/Course> a owl:Class ;
    rdfs:label "Course" .

<https://example.org/school/class/Department> a owl:Class ;
    rdfs:label "Department" .

<https://example.org/school/prop/teaches> a owl:ObjectProperty ;
    rdfs:domain <https://example.org/school/class/Teacher> ;
    rdfs:range <https://example.org/school/class/Course> ;
    rdfs:label "teaches" .

<https://example.org/school/prop/enrollsIn> a owl:ObjectProperty , owl:TransitiveProperty ;
    rdfs:domain <https://example.org/school/class/Student> ;
    rdfs:range <https://example.org/school/class/Course> ;
    rdfs:label "enrollsIn" .

<https://example.org/school/prop/offers> a owl:ObjectProperty ;
    rdfs:domain <https://example.org/school/class/Department> ;
    rdfs:range <https://example.org/school/class/Course> ;
    rdfs:label "offers" .
",
  "target_property": "https://example.org/school/prop/enrollsIn"
}
